const client = $input.item.json;
const invoiceNumber = `INV-${new Date().getFullYear()}${String(new Date().getMonth()+1).padStart(2,'0')}-${String(Math.floor(Math.random()*9000)+1000)}`;
const issueDate = new Date().toLocaleDateString('en-US',{year:'numeric',month:'long',day:'numeric'});
const dueDate = new Date(Date.now()+30*24*60*60*1000).toLocaleDateString('en-US',{year:'numeric',month:'long',day:'numeric'});
const monthlyRate = parseFloat(client.MonthlyRate||0);
const taxRate = parseFloat(client.TaxRate||0.1);
const taxAmount = monthlyRate*taxRate;
const totalAmount = monthlyRate+taxAmount;
const html = `<!DOCTYPE html><html><body style='font-family:Arial,sans-serif;color:#333;padding:40px'><h1 style='color:#1a1a2e'>INVOICE</h1><p><strong>Invoice #:</strong> ${invoiceNumber}</p><p><strong>Issue Date:</strong> ${issueDate}</p><p><strong>Due Date:</strong> ${dueDate}</p><hr/><p><strong>Bill To:</strong><br>${client.ClientName||'Client'}<br>${client.ClientEmail||''}</p><table style='width:100%;border-collapse:collapse;margin-top:20px'><tr style='background:#1a1a2e;color:white'><th style='padding:10px;text-align:left'>Description</th><th style='padding:10px;text-align:right'>Amount</th></tr><tr><td style='padding:10px;border-bottom:1px solid #eee'>${client.ServiceDescription||'Monthly Retainer'}</td><td style='padding:10px;text-align:right;border-bottom:1px solid #eee'>$${monthlyRate.toFixed(2)}</td></tr><tr><td style='padding:10px'>Tax (${(taxRate*100).toFixed(0)}%)</td><td style='padding:10px;text-align:right'>$${taxAmount.toFixed(2)}</td></tr><tr style='font-weight:bold;font-size:18px'><td style='padding:10px'>Total Due</td><td style='padding:10px;text-align:right;color:#1a1a2e'>$${totalAmount.toFixed(2)}</td></tr></table><p style='margin-top:30px;color:#666'>Payment due within 30 days. Thank you for your business!</p></body></html>`;
return { clientName: client.ClientName, clientEmail: client.ClientEmail, invoiceNumber, issueDate, dueDate, totalAmount: totalAmount.toFixed(2), invoiceHtml: html };
